   101|void AcousticalEngine::engineLoop() {
   102|    std::vector<float> block(fftSamples(config_.fftSize));
   103|    const int fftN = fftSamples(config_.fftSize);
   104|
   105|    while (running_.load()) {
   106|        const auto tickStart = std::chrono::steady_clock::now();
   107|        const long long now = nowMs();
   108|
   109|        // 1. Tick de los tres ecuas dinámicos (cada 10 ms, valores se ajustan aquí)
   110|        std::vector<float> measured;
   111|        {
   112|            std::lock_guard<std::mutex> lock(secondaryMutex_);
   113|            measured = lastMeasuredLevels_;
   114|        }
   115|        if (!measured.empty()) {
   116|            for (int i = 0; i < kDynamicEqCount; ++i) {
   117|                if (!sweeperEnabled_[i]) continue;
   118|                if (auto step = sweepers_[i]->step(measured, now))
   119|                    if (onSweep) onSweep(static_cast<SweepProcess>(i), *step);
   120|            }
   121|        }
   122|
   123|        // 2. Análisis FFT cada analysisInterval ms
   124|        bool doAnalysis = (now - lastAnalysisMs_.load()) >= analysisIntervalMs(config_.analysisInterval);
   125|        if (doAnalysis) {
   126|            bool haveBlock = false;
   127|            {
   128|                std::lock_guard<std::mutex> lock(ringMutex_);
   129|                if (static_cast<int>(ring_.size()) >= fftN) {
   130|                    const int start = static_cast<int>(ring_.size()) - fftN;
   131|                    std::copy_n(std::next(ring_.begin(), start), fftN, block.begin());
   132|                    haveBlock = true;
   133|                }
   134|            }
   135|            if (haveBlock) analyzeFrame(block, inputSampleRate_.load());
   136|            lastAnalysisMs_.store(now);
   137|        }
   138|
   139|        // Ritmo de tick de 10 ms
   140|        const auto elapsed = std::chrono::steady_clock::now() - tickStart;
   141|        const auto period = std::chrono::milliseconds(SweeperProcessor::TICK_MS);
   142|        if (elapsed < period) std::this_thread::sleep_for(period - elapsed);
   143|    }
