   246|float AcousticalEngine::supportTaper(float freqHz, const SupportBand& band) const {
   247|    if (band.gainDb == 0.0f || band.frequencyHz <= 0.0f) return 0.0f;
   248|    const float octaves = std::abs(std::log10(freqHz / band.frequencyHz));
   249|    const float width = 1.0f / std::max(band.q, 0.5f);
   250|    return octaves < width ? band.gainDb * (1.0f - octaves / width) : 0.0f;
   251|}
