   253|float AcousticalEngine::supportGainAt(float freqHz) const {
   254|    float gain = 0.0f;
   255|    for (const auto& eqBands : supportBandsByEq_)
   256|        for (const auto& band : eqBands) gain += supportTaper(freqHz, band);
   257|    return gain;
