   260|std::vector<float> AcousticalEngine::addSupportGains(const std::vector<float>& gains, int eqIndex) const {
   261|    const auto& support = supportBandsByEq_[eqIndex];
   262|    if (support.empty()) return gains;
   263|    std::vector<float> out = gains;
   264|    for (int b = 0; b < static_cast<int>(out.size()); ++b) {
   265|        float extra = 0.0f;
   266|        for (const auto& band : support) extra += supportTaper(bandFrequencies_[b], band);
   267|        out[b] = std::clamp(out[b] + extra, -DynamicEqConfig::MAX_GAIN_DB, DynamicEqConfig::MAX_GAIN_DB);
   268|    }
   269|    return out;
